def get_page(endpoint: str) -> Dict[str, Any]:
    logger.info(f"ENDPOINT: {endpoint}")

    try:
        return json.loads(urlopen(Request(endpoint)).read().decode("utf-8"))

    except HTTPError as errh:
        logger.error("Http Error:: %s" % errh)
        raise errh
    except Exception as err:
        logger.error("Something Else Error:: %s" % err)
        raise err

def handler(*args, **kwargs) -> str:

    client = boto3.client("glue")
    crawler_name = get_crawler_name(args)

    try:
        client.start_crawler(Name=crawler_name)

    except client.exceptions.CrawlerRunningException:
        logger.info(f"Crawler {crawler_name} is already running.")
    except Exception as e:
        logger.error(f"Crawler {crawler_name} Error: ${str(e)}")
        raise Exception(f"Crawler {crawler_name} Error: ${str(e)}")

    state = check_state(client, crawler_name)

    return state

def test_handler():
    mock_athena = Mock()
    test_id = uuid.uuid4()
    with patch("boto3.client", Mock(return_value=mock_athena)):
        mock_athena.start_query_execution = Mock(return_value={"QueryExecutionId": test_id})
        mock_athena.get_query_execution = Mock(
            return_value={
                "QueryExecution": {"QueryExecutionId": test_id, "Status": {"State": "SUCCEEDED"},}
            }
        )

        query_ids = handler(
            {
                "SQL_QUERY_FILES": "CVAS.sql",
                "ATHENA_DATABASE": athena_database,
                "WORKGROUP": workgroup,
                "TABLENAME": table_name,
            },
        )
        assert query_ids == [test_id]

