    mock_crawler = Mock()
    with patch("boto3.client", Mock(return_value=mock_crawler)):
        mock_crawler.start_crawler = Mock(
            return_value={
                "ResponseMetadata": {
                    "RequestId": "31cfb743-ffe9-11e9-82e6-dde5d132791c",
